<script lang="ts">
  import { onMount } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { Orbit, Plus, Play, Wrench, FolderOpen, ArrowUpLeft, ShieldCheck, Layers, Search, RefreshCw, Check, X, Link, Monitor, Info, Trash2, MoreHorizontal } from 'lucide-svelte';
  type Profile = {id:string;name:string;kind:string;source:string;color:string;number:number;healthy:boolean;detail:string;folder:string};
  type Existing = {id:string;name:string;shortcut:string;target:string;available:boolean};
  type Snapshot = {profiles:Profile[];existing:Existing[];root:string};
  let state:Snapshot = {profiles:[],existing:[],root:''};
  let detected:{name:string;path:string}[]=[];
  let busy=false, loading=true, modal=false, accepted=false;
  let query='', name='', kind='claude', source='', color='#cf8365', notice='', error='';
  let tab='all';
  let deleting: {id:string;name:string;external:boolean}|null=null;
  $: profiles = state.profiles.filter(p=>(tab==='all'||p.kind===tab)&&p.name.toLowerCase().includes(query.toLowerCase()));
  // Keep local UI state reactive with Svelte's legacy mode.
  async function run<T>(task:()=>Promise<T>, success='') { busy=true; error=''; notice=''; try { const result=await task(); notice=success; return result; } catch(e) { error=String(e); } finally { busy=false; } }
  async function refresh() { const value=await run(()=>invoke<Snapshot>('snapshot')); if(value) state=value; loading=false; }
  onMount(async()=>{ await refresh(); const scanned=await run(()=>invoke<Snapshot>('scan_existing'));if(scanned)state=scanned; try { detected=await invoke('detect_apps'); } catch(e) {error=String(e);} });
  async function browse() { const value=await invoke<string|null>('choose_executable'); if(value) source=value; }
  function nextName() { const names=[...state.profiles.map(p=>p.name),...state.existing.map(p=>p.name)].filter(n=>n.toLowerCase().includes(kind)); const numbers=names.map(n=>Number(n.match(/(\d+)\s*$/)?.[1]||0)); return `${kind==='claude'?'Claude':kind==='codex'?'Codex':'Profile'} ${Math.max(0,...numbers)+1}`; }
  function nextColor() { return ['#cf8365','#698dcc','#49af99','#a478c5','#d1a343','#be688f','#608fbd','#7ca65b'].find(c=>!state.profiles.some(p=>p.color.toLowerCase()===c))||'#'+Math.floor(Math.random()*0xffffff).toString(16).padStart(6,'0'); }
  function newProfile() { name=nextName();color=nextColor(); source=detected.find(a=>a.name.toLowerCase().includes(kind))?.path||''; accepted=false; modal=true; }
  function kindChanged() { source=detected.find(a=>a.name.toLowerCase().includes(kind))?.path||''; color=nextColor(); name=nextName();color=nextColor(); }
  async function create() { const value=await run(()=>invoke<Snapshot>('create_profile',{name,kind,source,color})); if(value){state=value;modal=false;notice='پروفایل مستقل ساخته شد. برای ورود، آن را اجرا کنید.';} }
  async function repair(p:Profile) { const value=await run(()=>invoke<Snapshot>('repair_profile',{id:p.id,source:null})); if(value){state=value;notice='فایل‌های برنامه بازسازی شدند؛ داده‌های پروفایل حفظ شد.';} }
  async function changeSource(p:Profile) { const value=await invoke<string|null>('choose_executable'); if(!value)return; const result=await run(()=>invoke<Snapshot>('repair_profile',{id:p.id,source:value}));if(result){state=result;notice='مسیر اصلی و فایل‌های کلون به‌روز شد.';} }
  async function scan() { const result=await run(()=>invoke<Snapshot>('scan_existing'));if(result){state=result;notice='میان‌برهای Claude و Codex در دسکتاپ و Start بررسی شدند.';} }
  async function remove() { if(!deleting)return; const result=await run(()=>invoke<Snapshot>(deleting!.external?'remove_existing':'remove_profile',{id:deleting!.id}));if(result){state=result;deleting=null;notice='از فهرست حذف شد.';} }
</script>
<div class="simple-app" dir="rtl">
  <header class="simple-header"><a class="brand" href="#home"><span class="brand-icon"><Orbit size={25}/></span><span>Orbit<span class="brand-sub">CLONER</span></span></a><button class="quiet" disabled={busy} onclick={scan}><RefreshCw size={16}/>پیدا کردن نسخه‌های قبلی</button></header>
  <main class="simple-main" id="home">
    <div class="heading"><div><h1>برنامه‌های من</h1><p>نسخه‌های جدا برای حساب‌های متفاوت</p></div><button class="primary" disabled={busy} onclick={newProfile}><Plus size={19}/>ساخت نسخهٔ جدید</button></div>
    {#if error}<div class="alert error" role="alert"><Info size={18}/><span dir="auto">{error}</span><button onclick={()=>error=''} aria-label="بستن"><X size={16}/></button></div>{/if}
    {#if notice}<div class="alert" role="status"><Check size={18}/><span>{notice}</span><button onclick={()=>notice=''} aria-label="بستن"><X size={16}/></button></div>{/if}
    {#if busy}<div class="working"><RefreshCw size={16} class="spin"/>در حال انجام… لطفاً صبر کنید.</div>{/if}
    {#if loading}<div class="empty">در حال خواندن…</div>{:else}
      {#if state.profiles.length===0 && state.existing.length===0}<div class="empty"><div class="empty-orbit"><Orbit size={44}/></div><h3>از کدام برنامه یک نسخهٔ دیگر می‌خواهی؟</h3><p>برنامه را انتخاب کن و به نسخهٔ تازه وارد شو.</p><button class="primary" disabled={busy} onclick={newProfile}><Plus size={18}/>ساخت نسخه</button></div>{/if}
      {#if state.profiles.length}<h2 class="list-title">نسخه‌های Orbit</h2><div class="simple-list">{#each state.profiles as p}<article class="simple-card"><div class="profile-icon" style={`--profile-color:${p.color}`}>{p.number}</div><div class="card-name"><h3>{p.name}</h3><small>{p.healthy?'آمادهٔ اجرا':'نیاز به ترمیم'}</small></div><button class="primary compact" disabled={busy||!p.healthy} onclick={()=>run(()=>invoke('launch_profile',{id:p.id}),'درخواست اجرا ارسال شد.')}><Play size={15}/>اجرا</button><details class="more"><summary aria-label="گزینه‌های نسخه"><MoreHorizontal size={21}/></summary><div class="menu"><button disabled={busy} onclick={()=>repair(p)}><Wrench size={15}/>ترمیم نسخه</button><button disabled={busy} onclick={()=>run(()=>invoke('create_shortcut',{id:p.id}),'میان‌بر روی دسکتاپ ساخته شد.')}><ArrowUpLeft size={15}/>میان‌بر دسکتاپ</button><button disabled={busy} onclick={()=>run(()=>invoke('open_folder',{id:p.id}))}><FolderOpen size={15}/>پوشهٔ نسخه</button><button disabled={busy} onclick={()=>changeSource(p)}>تغییر فایل اصلی</button><button disabled={busy||p.kind==='electron'} onclick={()=>run(()=>invoke('register_links',{id:p.id}),'گزینهٔ لینک ثبت شد؛ نمایش آن به ویندوز و مرورگر بستگی دارد.')}><Link size={15}/>ثبت لینک مرورگر</button><button class="danger" disabled={busy} onclick={()=>deleting={id:p.id,name:p.name,external:false}}><Trash2 size={15}/>حذف نسخه</button></div></details></article>{/each}</div>{/if}
      {#if state.existing.length}<h2 class="list-title">نسخه‌های قبلی <span>پیداشده در ویندوز</span></h2><div class="simple-list">{#each state.existing as p}<article class="simple-card"><div class="existing-icon">{p.name.toLowerCase().includes('claude')?'✳':'⌘'}</div><div class="card-name"><h3>{p.name}</h3><small>{p.available?'میان‌بر موجود':'مسیر میان‌بر پیدا نشد'}</small></div><button class="secondary compact" disabled={busy||!p.available} onclick={()=>run(()=>invoke('launch_existing',{id:p.id}))}><Play size={15}/>اجرا</button><button class="icon-button danger" title="حذف از فهرست Orbit" disabled={busy} onclick={()=>deleting={id:p.id,name:p.name,external:true}}><Trash2 size={17}/></button><details class="existing-details"><summary>اطلاعات</summary><p dir="auto">{p.shortcut}</p><p>این نسخه با ابزار دیگری ساخته شده است؛ فعلاً اجرا و حذف از فهرست در دسترس است. ترمیم جداسازی آن هنوز پشتیبانی نمی‌شود.</p></details></article>{/each}</div>{/if}
    {/if}
    <footer><span>نسخهٔ آزمایشی · داده‌ها روی همین دستگاه</span><button onclick={()=>run(()=>invoke('open_folder',{id:null}))}><FolderOpen size={14}/>پوشهٔ داده‌ها</button></footer>
  </main>
</div>
{#if modal}<div class="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1" dir="rtl"><div class="modal-heading"><h2 id="modal-title">یک نسخهٔ تازه بساز</h2><button class="icon-button" disabled={busy} onclick={()=>modal=false} aria-label="بستن"><X size={20}/></button></div><label>از کدام برنامه؟<select bind:value={kind} onchange={kindChanged} disabled={busy}><option value="claude">Claude</option><option value="codex">Codex</option><option value="electron">برنامهٔ دیگر</option></select></label><label>اسم نسخه<input bind:value={name} maxlength="48" disabled={busy}/></label><div class="color-choices"><span>رنگ آیکون</span>{#each ['#cf8365','#698dcc','#49af99','#a478c5','#d1a343','#be688f'] as c}<button class:selected={color===c} style={`background:${c}`} onclick={()=>color=c} disabled={busy} aria-label={`رنگ ${c}`}>{#if color===c}<Check size={17}/>{/if}</button>{/each}</div><details class="advanced" open={!source}><summary>تنظیمات پیشرفته</summary><label>فایل اجرایی برنامهٔ اصلی<div class="path-input"><input bind:value={source} dir="ltr" placeholder="C:\…\app.exe" disabled={busy}/><button disabled={busy} onclick={browse} aria-label="انتخاب فایل"><FolderOpen size={18}/></button></div></label><label>رنگ دلخواه<input type="color" bind:value={color} disabled={busy}/></label><p>هر نسخه پوشهٔ داده و حساب جدا دارد. برنامهٔ اصلی تغییر نمی‌کند.</p></details><p class="short-warning">روش آزمایشی است: امضای کپی تغییر می‌کند و ورود از مرورگر ممکن است به تنظیم جدا نیاز داشته باشد. برای هر نسخه فضای یک کپی کامل لازم است.</p>{#if error}<div class="alert error" dir="auto">{error}</div>{/if}<button class="primary full" disabled={busy||!name.trim()||!source} onclick={create}>{#if busy}<RefreshCw size={18} class="spin"/>در حال ساخت…{:else}<Plus size={18}/>ساخت نسخه{/if}</button></div></div>{/if}
{#if deleting}<div class="overlay"><div class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="delete-title" tabindex="-1" dir="rtl"><h2 id="delete-title">{deleting.name} حذف شود؟</h2><p class="delete-description">{deleting.external?'فقط از فهرست Orbit حذف می‌شود. برنامه، میان‌بر ویندوز و حساب آن باقی می‌مانند.':'نسخه از فهرست حذف و فایل‌ها و داده‌هایش به پوشهٔ trash در کنار داده‌های Orbit منتقل می‌شوند. ابتدا این نسخه را ببندید.'}</p><div class="delete-actions"><button class="secondary" disabled={busy} onclick={()=>deleting=null}>انصراف</button><button class="delete-button" disabled={busy} onclick={remove}><Trash2 size={16}/>حذف</button></div></div></div>{/if}
